test('atomic first-buy receipt separates the SPL seed from spending and preserves native trade totals',async()=>{
  for(const native of [false,true]){
    const f=await fixture();if(!native)f.launch.quoteMint=String(k());const a=f.adapter.launchAddresses(f.config,f.launch,{user:String(f.creator)}),state={phase:0,sqrtMaxPrice:'2',liquidity:'99',claimedProtocolQuote:'0'},op={action:'initialize',wallet:String(f.creator),signature:'receipt',signedTransaction:'saved-wire',bundle:{blockhash:{lastValidBlockHeight:500},trade:{input:'1000',minimum:'990',quoteAccount:String(a.userQuoteAta),venue:'damm-v2'}}};
    const transfer=(source,destination,value)=>({programId:TOKEN_PROGRAM_ID,parsed:{type:'transferChecked',info:{source:String(source),destination:String(destination),mint:f.launch.quoteMint,tokenAmount:{amount:String(value)}}}}),issuance={programId:TOKEN_PROGRAM_ID,parsed:{type:'mintTo',info:{mint:f.launch.mint,account:String(a.baseAta),amount:c.DAMM_PUMP_SUPPLY}}},ix=[issuance,transfer(a.quoteAta,a.dammQuoteVault,1),transfer(a.userQuoteAta,a.dammQuoteVault,1000)];if(!native)ix.push(transfer(a.userQuoteAta,a.quoteAta,1));
    const row=(mint,value)=>({mint,owner:String(f.creator),uiTokenAmount:{amount:String(value)}}),receipt={slot:110,blockTime:1900000000,transaction:{message:{instructions:[],accountKeys:[]}},meta:{err:null,preTokenBalances:[row(f.launch.quoteMint,2000)],postTokenBalances:[row(f.launch.quoteMint,native?1000:999),row(f.launch.mint,1000)],innerInstructions:[{instructions:ix}]}};
    f.connection.getSignatureStatuses=async()=>({value:[{confirmationStatus:'finalized',err:null}]});f.connection._rpcRequest=async()=>({result:{meta:{err:null},transaction:['saved-wire','base64']}});f.connection.getParsedTransaction=async()=>receipt;f.adapter.rawState=async()=>({state,addresses:a,slot:111});f.adapter.dammSnapshot=async()=>({state,addresses:a,pool:{sqrtPrice:new BN(1)},slot:111});
    const minted=mintInfo();minted.data[44]=6;const nftData=Buffer.alloc(165);AccountLayout.encode({mint:a.nftMint,owner:a.authority,amount:1n,delegateOption:0,delegate:PublicKey.default,state:1,isNativeOption:0,isNative:0n,delegatedAmount:0n,closeAuthorityOption:0,closeAuthority:PublicKey.default},nftData);f.connection.getMultipleAccountsInfo=async()=>[minted,{owner:TOKEN_2022_PROGRAM_ID,data:nftData,executable:false},{owner:a.dammProgram,data:Buffer.from([0]),executable:false}];f.adapter.cp._program.coder.accounts.decode=()=>({pool:a.dammPool,nftMint:a.nftMint,unlockedLiquidity:new BN(99)});
    const result=await f.adapter.reconcile(f.config,op,f.launch);assert.equal(result.state,'finalized');assert.equal(result.trade.quoteRaw,'1000');assert.equal(result.initialQuoteSeedRaw,'1');assert.equal(result.creatorQuoteSeedRaw,native?'0':'1');
    ix[1]=transfer(a.quoteAta,a.dammQuoteVault,2);await assert.rejects(f.adapter.reconcile(f.config,op,f.launch),/one-unit DAMM quote seed/);
  }
});

function nativeInfo(owner,value=0n){const data=Buffer.alloc(165);AccountLayout.encode({mint:NATIVE_MINT,owner,amount:value,delegateOption:0,delegate:PublicKey.default,state:1,isNativeOption:1,isNative:2000000n,delegatedAmount:0n,closeAuthorityOption:0,closeAuthority:PublicKey.default},data);return {owner:TOKEN_PROGRAM_ID,data,lamports:2000000+Number(value),executable:false};}
function simInfo(info){return {...info,owner:String(info.owner),data:[info.data.toString('base64'),'base64']};}
