 assert.equal(next.action,'prepare-buy');assert.equal(next.addresses.mint,f.launch.mint);assert.equal(next.review.firstBuyRaw,'10000000');assert.equal(next.review.nativeAccountRentLamports,'2000000');assert.equal(next.review.maxWalletDebitLamports,'2010000');assert.deepEqual(next.addressLookupTables,f.launch.lookupTables);assertSdkWalletGuardFits(VersionedTransaction.deserialize(Buffer.from(next.unsignedTransaction,'base64')),next,f.creator,[f.table]);
