test('atomic simulation accepts compiled transfers and refuses omitted, misdirected, duplicate or excessive debit proofs',async()=>{
 for(const mutation of ['compiled','missing','source','duplicate','excess','base-minimum']){
  const f=await finalBuyFixture(),base=f.connection.simulateTransaction;f.connection.simulateTransaction=async(tx,options)=>{const result=await base(tx,options),group=result.value.innerInstructions[0],rows=group.instructions;
   if(mutation==='compiled'){const keys=tx.message.getAccountKeys({addressLookupTableAccounts:[f.table]}),at=pubkey=>{for(let i=0;i<keys.length;i++)if(String(keys.get(i))===String(pubkey))return i;throw Error('fixture key missing');};group.instructions=rows.map(row=>{const i=row.parsed.info,data=Buffer.alloc(10);data[0]=12;data.writeBigUInt64LE(BigInt(i.tokenAmount.amount),1);data[9]=i.tokenAmount.decimals;return{programIdIndex:at(row.programId),accounts:[i.source,i.mint,i.destination,i.authority].map(at),data:bs58.encode(data)};});}
   if(mutation==='missing')delete result.value.innerInstructions;if(mutation==='source')rows[0].parsed.info.source=String(k());if(mutation==='duplicate')rows.push(rows[0]);if(mutation==='excess')rows[0].parsed.info.tokenAmount.amount='100000001';if(mutation==='base-minimum')rows[1].parsed.info.tokenAmount.amount='1';return result;
  };
  const task=f.adapter.prepare(f.config,{action:'buy',wallet:String(f.buyer),launch:f.launch,amountRaw:'100000000'});if(mutation==='compiled')assert.equal((await task).atomicGraduation,true);else await assert.rejects(task,/simulation proof|quote debit|token receipt/);
 }
});
