test('actual SDK launch packets accept wallet assertions through saved frozen lookups',async()=>{
 for(const action of ['configure','initialize']){
  const f=await fixture(),bundle=await f.adapter.prepare(f.config,{action,wallet:String(f.creator),relayer:String(f.relayer),launch:f.launch});
  const original=VersionedTransaction.deserialize(Buffer.from(bundle.unsignedTransaction,'base64')),builder=TransactionMessage.decompile(original.message,{addressLookupTableAccounts:action==='initialize'?[f.table]:[]});
  builder.instructions.push(new TransactionInstruction({programId:new PublicKey('L2TExMFKdjpN9kozasaurPirfHy9P8sbXoAN1qA3S95'),keys:[{pubkey:f.creator,isSigner:false,isWritable:false}],data:Buffer.concat([Buffer.from([5,0,0]),Buffer.alloc(8),Buffer.from([4])])}));
  const actual=new VersionedTransaction(builder.compileToV0Message(action==='initialize'?[f.table]:[]));assert(actual.serialize().length<=1232);assert.notDeepEqual(Buffer.from(actual.message.serialize()),Buffer.from(original.message.serialize()));assert.deepEqual(validateDammPumpWalletMessage(actual,bundle),{changed:true,guardCount:1});
 }
});

function assertSdkWalletGuardFits(tx,bundle,payer,tables){
 const builder=TransactionMessage.decompile(tx.message,{addressLookupTableAccounts:tables});
 builder.instructions.push(new TransactionInstruction({programId:new PublicKey('L2TExMFKdjpN9kozasaurPirfHy9P8sbXoAN1qA3S95'),keys:[{pubkey:payer,isSigner:false,isWritable:false}],data:Buffer.concat([Buffer.from([5,0,0]),Buffer.alloc(8),Buffer.from([4])])}));
 const actual=new VersionedTransaction(builder.compileToV0Message(tables));assert(actual.serialize().length<=1232);assert.deepEqual(validateDammPumpWalletMessage(actual,bundle),{changed:true,guardCount:1});
}

test('PumpSwap setup fixes the compute budget before review and avoids Phantom fee injection',async t=>{
 const f=await fixture(),bundle=await f.adapter.prepare(f.config,{action:'configure',wallet:String(f.creator),launch:f.launch}),tx=VersionedTransaction.deserialize(Buffer.from(bundle.unsignedTransaction,'base64')),builder=TransactionMessage.decompile(tx.message);
 const budget=builder.instructions.filter(ix=>ix.programId.equals(ComputeBudgetProgram.programId));
 assert.equal(budget.length,2);assert.deepEqual(budget.map(ix=>ix.data[0]),[2,3]);assert.equal(budget[0].data.readUInt32LE(1),500000);assert.equal(budget[1].data.readBigUInt64LE(1),0n);
 assert.equal(tx.signatures.length,1);assert(tx.signatures[0].every(byte=>byte===0));
 // Reproduce Phantom's documented automatic fee augmentation trigger: unsigned
 // packets lacking a compute budget. This is a compatibility model, not a live
 // Phantom extension test. The old setup packet satisfies that trigger.
 const legacyBuilder=new TransactionMessage({...builder,instructions:builder.instructions.filter(ix=>!ix.programId.equals(ComputeBudgetProgram.programId))}),legacy=new VersionedTransaction(legacyBuilder.compileToV0Message());
 const legacyBundle={...bundle,unsignedTransaction:Buffer.from(legacy.serialize()).toString('base64')};
 const augmented=new VersionedTransaction(new TransactionMessage({...legacyBuilder,instructions:[ComputeBudgetProgram.setComputeUnitLimit({units:500000}),ComputeBudgetProgram.setComputeUnitPrice({microLamports:1000}),...legacyBuilder.instructions]}).compileToV0Message());
 // Wallet-chosen priority fees are paid by the developer wallet and accepted
 // within the 0.01 SOL cap; reviewed launch instructions stay locked.
 assert.deepEqual(validateDammPumpWalletMessage(augmented,legacyBundle),{changed:true,guardCount:0});
 assert.deepEqual(validateDammPumpWalletMessage(tx,bundle),{changed:false,guardCount:0});assertSdkWalletGuardFits(tx,bundle,f.creator,[]);
 builder.instructions[1]=ComputeBudgetProgram.setComputeUnitPrice({microLamports:1000});
 const changed=new VersionedTransaction(builder.compileToV0Message());assert.deepEqual(validateDammPumpWalletMessage(changed,bundle),{changed:true,guardCount:0});
 builder.instructions[0]=ComputeBudgetProgram.setComputeUnitLimit({units:1400000});builder.instructions[1]=ComputeBudgetProgram.setComputeUnitPrice({microLamports:10000000});
 const excessive=new VersionedTransaction(builder.compileToV0Message());assert.throws(()=>validateDammPumpWalletMessage(excessive,bundle),error=>error.code==='WALLET_TRANSACTION_REJECTED'&&error.walletValidationReason==='wallet priority fee above limit');
 assert.equal(bundle.review.networkFeeLamports,'10000');assert.equal(bundle.review.maxWalletDebitLamports,'50000000');
 t.diagnostic(`Setup packet ${tx.serialize().length} bytes; legacy ${legacy.serialize().length} bytes; 2 explicit setup fee instructions.`);
});

test('public and test initialization fix both compute limit and zero priority price',async()=>{
 for(const Adapter of [DammPumpClientAdapter,DammPumpTestClientAdapter,DammPumpFeeClientAdapter]){
  const f=await fixture(),adapter=new Adapter({connection:f.connection,deploymentVerifier:async()=>({chainEnabled:true}),venueVerifier:async()=>({verified:true})});
  // buildTransaction is shared by normal initialization and all derived modes;
  // both fields are present before wallet review and network-fee simulation.
  const tx=await adapter.buildTransaction(f.config,f.launch,String(f.creator),[],'initialize',await f.connection.getLatestBlockhash());
  const first=tx.message.compiledInstructions[0];assert.equal(tx.message.staticAccountKeys[first.programIdIndex].toBase58(),ComputeBudgetProgram.programId.toBase58());assert.equal(first.data[0],2);assert.equal(Buffer.from(first.data).readUInt32LE(1),1400000);assert.equal(tx.message.compiledInstructions.length,2);const price=tx.message.compiledInstructions[1];assert.equal(price.data[0],3);assert.equal(Buffer.from(price.data).readBigUInt64LE(1),0n);
 }
});

test('signed Phantom fee augmentation and guards are accepted for legacy and corrected setups',async t=>{
 const bytes=tx=>Buffer.from(tx.serialize()).toString('base64');
 const phantomModel=(source,payer,{guard=false}={})=>{
  const builder=TransactionMessage.decompile(source.message),budget=builder.instructions.some(ix=>ix.programId.equals(ComputeBudgetProgram.programId));
  if(source.signatures.every(signature=>signature.every(byte=>byte===0))&&!budget)builder.instructions.unshift(ComputeBudgetProgram.setComputeUnitLimit({units:500000}),ComputeBudgetProgram.setComputeUnitPrice({microLamports:1000}));
  if(guard)builder.instructions.push(new TransactionInstruction({programId:new PublicKey('L2TExMFKdjpN9kozasaurPirfHy9P8sbXoAN1qA3S95'),keys:[{pubkey:payer.publicKey,isSigner:false,isWritable:false}],data:Buffer.concat([Buffer.from([5,0,0]),Buffer.alloc(8),Buffer.from([4])])}));
  const signed=new VersionedTransaction(builder.compileToV0Message());signed.sign([payer]);return signed;
 };
 let largest=0;
 for(const Adapter of [DammPumpClientAdapter,DammPumpTestClientAdapter,DammPumpFeeClientAdapter])for(const kind of ['sol','sol-first-buy','paired-asset']){
  const f=await fixture();f.adapter=new Adapter({connection:f.connection,deploymentVerifier:async()=>({chainEnabled:true}),venueVerifier:async()=>({verified:true})});
  if(kind==='sol-first-buy')f.launch.firstBuyRaw='10000000';
  if(kind==='paired-asset'){const quote=k();f.launch.quoteMint=String(quote);f.connection.getAccountInfo=async key=>key.equals(quote)?mintInfo():null;f.adapter.wallet=async()=>({quoteBalanceRaw:'1'});}
  const bundle=await f.adapter.prepare(f.config,{action:'configure',wallet:String(f.creator),launch:f.launch}),original=VersionedTransaction.deserialize(Buffer.from(bundle.unsignedTransaction,'base64'));
  const builder=TransactionMessage.decompile(original.message);builder.instructions=builder.instructions.filter(ix=>!ix.programId.equals(ComputeBudgetProgram.programId));const legacy=new VersionedTransaction(builder.compileToV0Message()),legacyBundle={...bundle,unsignedTransaction:bytes(legacy)};
  for(const guard of [false,true]){
   const augmented=phantomModel(legacy,f.creatorKeypair,{guard});assert.equal(bytes(verifyPublicWalletTransaction(bytes(augmented),legacyBundle,String(f.creator),String(f.relayer))),bytes(augmented));
   const signed=phantomModel(original,f.creatorKeypair,{guard});largest=Math.max(largest,signed.serialize().length);assert(signed.serialize().length<=1232);
   const verified=verifyPublicWalletTransaction(bytes(signed),bundle,String(f.creator),String(f.relayer));assert.equal(bytes(verified),bytes(signed));
  }
 }
 t.diagnostic(`Largest signed setup with Lighthouse guard across SOL, first-buy, paired-asset and controller modes: ${largest} bytes.`);
});
